export function ClaimProgress({ claimed, total, compact = false }: { claimed: number; total: number; compact?: boolean }) {
  const percentage = Math.min(100, Math.round((claimed / total) * 100));
  const radius = 14;
  const circumference = 2 * Math.PI * radius;
  const offset = circumference - (percentage / 100) * circumference;

  if (compact) {
    return (
      <div className="min-w-28" aria-label={`${claimed} of ${total} servings claimed`}>
        <div className="mb-1.5 flex justify-between text-xs"><span>{claimed} / {total}</span><span className="text-muted-foreground">{percentage}%</span></div>
        <div className="h-1.5 overflow-hidden rounded-full bg-muted"><div className="h-full rounded-full bg-primary" style={{ width: `${percentage}%` }} /></div>
      </div>
    );
  }

  return (
    <div className="flex items-center gap-2.5" aria-label={`${claimed} of ${total} servings claimed`}>
      <svg className="size-9 -rotate-90" viewBox="0 0 36 36" role="img" aria-hidden="true">
        <circle cx="18" cy="18" r={radius} fill="none" stroke="var(--muted)" strokeWidth="3" />
        <circle cx="18" cy="18" r={radius} fill="none" stroke="var(--primary)" strokeWidth="3" strokeLinecap="round" strokeDasharray={circumference} strokeDashoffset={offset} />
      </svg>
      <div>
        <p className="font-medium tabular-nums">{claimed} / {total}</p>
        <p className="text-xs text-muted-foreground">servings</p>
      </div>
    </div>
  );
}
