import { Badge } from "@/components/ui/badge";
import type { ClaimStatus, FoodStatus } from "@/lib/types";

const foodStatusConfig: Record<FoodStatus, { label: string; variant: "default" | "neutral" | "warning" | "danger"; dot: string }> = {
  available: { label: "Available", variant: "default", dot: "bg-primary" },
  "almost-claimed": { label: "Almost claimed", variant: "warning", dot: "bg-warning" },
  claimed: { label: "Claimed", variant: "neutral", dot: "bg-foreground" },
  collected: { label: "Collected", variant: "default", dot: "bg-primary" },
  expired: { label: "Expired", variant: "danger", dot: "bg-danger" },
};

const claimStatusConfig: Record<ClaimStatus, { label: string; variant: "default" | "neutral" | "danger"; dot: string }> = {
  reserved: { label: "Reserved", variant: "neutral", dot: "bg-foreground" },
  collected: { label: "Collected", variant: "default", dot: "bg-primary" },
  missed: { label: "Missed", variant: "danger", dot: "bg-danger" },
};

export function FoodStatusBadge({ status }: { status: FoodStatus }) {
  const config = foodStatusConfig[status];
  return <Badge variant={config.variant}><span className={`size-1.5 rounded-full ${config.dot}`} aria-hidden="true" />{config.label}</Badge>;
}

export function ClaimStatusBadge({ status }: { status: ClaimStatus }) {
  const config = claimStatusConfig[status];
  return <Badge variant={config.variant}><span className={`size-1.5 rounded-full ${config.dot}`} aria-hidden="true" />{config.label}</Badge>;
}
